// ICON-V4 — آیکون به‌صورت متن (base64) داخل همین فایل است، پس هنگام آپلود خراب نمی‌شود
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const B64="";
const png=Buffer.from(B64,'base64');
if(png.slice(0,8).toString('hex')!=='89504e470d0a1a0a'){console.log('ICON-V4: bad png data');process.exit(1)}
const res='android/app/src/main/res',man='android/app/src/main/AndroidManifest.xml';
if(!fs.existsSync(res)||!fs.existsSync(man)){console.log('ICON-V4: no android project');process.exit(1)}
for(const d of ['mipmap-mdpi','mipmap-hdpi','mipmap-xhdpi','mipmap-xxhdpi','mipmap-xxxhdpi']){
  fs.mkdirSync(path.join(res,d),{recursive:true});
  for(const n of ['bazaar_icon','ic_launcher','ic_launcher_round'])fs.writeFileSync(path.join(res,d,n+'.png'),png);
}
for(const f of ['mipmap-anydpi-v26/ic_launcher.xml','mipmap-anydpi-v26/ic_launcher_round.xml','drawable-v24/ic_launcher_foreground.xml','drawable/ic_launcher_background.xml']){
  try{fs.unlinkSync(path.join(res,f))}catch(e){}
}
let m=fs.readFileSync(man,'utf8');
m=m.replace(/android:icon="[^"]*"/,'android:icon="@mipmap/bazaar_icon"');
if(/android:roundIcon="/.test(m))m=m.replace(/android:roundIcon="[^"]*"/,'android:roundIcon="@mipmap/bazaar_icon"');
else m=m.replace('<application','<application android:roundIcon="@mipmap/bazaar_icon"');
fs.writeFileSync(man,m);
console.log('ICON-V4 manifest:',(m.match(/android:(icon|roundIcon)="[^"]*"/g)||[]).join(' '));
console.log('ICON-V4 png bytes:',png.length,'sha256:',crypto.createHash('sha256').update(png).digest('hex').slice(0,12));
console.log('ICON-V4 replaced');
